@sig trait RequestQualification_Api {
  def id: Art.BridgeId
  def requestSample_Id : Art.PortId
  def qualifiedRequest_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualifiedRequest: Mining_Cargo_Transfer_Supervisor.QualifiedRequest.Type = $

  def put_qualifiedRequest(value : Mining_Cargo_Transfer_Supervisor.QualifiedRequest.Type) : Unit = {
    Contract(
      Modifies(qualifiedRequest),
      Ensures(
        qualifiedRequest == value
      )
    )
    Spec {
      qualifiedRequest = value
    }

    Art.putValue(qualifiedRequest_Id, Mining_Cargo_Transfer_Supervisor.QualifiedRequest_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class RequestQualification_Initialization_Api (
  val id: Art.BridgeId,
  val requestSample_Id : Art.PortId,
  val qualifiedRequest_Id : Art.PortId) extends RequestQualification_Api

@datatype class RequestQualification_Operational_Api (
  val id: Art.BridgeId,
  val requestSample_Id : Art.PortId,
  val qualifiedRequest_Id : Art.PortId) extends RequestQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var requestSample: Mining_Cargo_Transfer_Supervisor.OffloadRequestSample = $

  def get_requestSample() : Option[Mining_Cargo_Transfer_Supervisor.OffloadRequestSample] = {
    Contract(
      Ensures(
        Res == Some(requestSample)
      )
    )
    val value : Option[Mining_Cargo_Transfer_Supervisor.OffloadRequestSample] = Art.getValue(requestSample_Id) match {
      case Some(Mining_Cargo_Transfer_Supervisor.OffloadRequestSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port requestSample.  Expecting 'Mining_Cargo_Transfer_Supervisor.OffloadRequestSample_Payload' but received ${v}")
        None[Mining_Cargo_Transfer_Supervisor.OffloadRequestSample]()
      case _ => None[Mining_Cargo_Transfer_Supervisor.OffloadRequestSample]()
    }
    return value
  }
}
